//
// ===========================================================
// 数据格式说明:
//
//   noteTypes        -- 所有音符种类的定义 (id/label/color/shape)
//   stepsPreTyped    -- Dict<step_id, List<int>>: 0=空格, 1+=noteTypes 中第 (n-1) 种 ★推荐用这个
//   stepsLongs       -- Dict<step_id, List<LongNote1>>: 长按音符 (留给未来引擎升级)
//   dishesPre        -- Dict<dish_id, List<DishStep>>: 菜品 = 步骤序列
//   notesPreTyped    -- Dict<dish_id, List<int>>: 已拼好的扁平带类型谱面 ★推荐
//   stepsPre         -- Dict<step_id, List<bool>>: 向后兼容 (只有 有/无, 丢失种类)
//   notesPre         -- Dict<dish_id, List<bool>>: 向后兼容扁平版
//
// 用法示例 (在 NoteManager 中根据种类选美术素材):
//
//   var list = NotesStatics.notesPreTyped["dish_001"];
//   for (int i = 0; i < list.Count; i++) {
//       int typeIdx = list[i];
//       if (typeIdx == 0) continue;            // 空格
//       var type = NotesStatics.noteTypes[typeIdx - 1];
//       Sprite art = LookupSpriteByTypeId(type.id);  // 需自己写
//       SpawnNote(art, ...);
//   }
// ===========================================================

// 用于"菜品 = 步骤序列"方案
[System.Serializable]
public class DishStep {
    public string stepId;
    public float gapAfter; // 该步骤之后到下一步骤之间的等待秒数
}

// 音符种类元数据
[System.Serializable]
public class NoteTypeInfo {
    public string id;     // 程序里用来索引美术素材的唯一标识
    public string label;  // 编辑器里看的中文标签
    public string color;  // 编辑器预览色, 形如 "#3b82f6"
    public string shape;  // "circle" / "diamond" / "square"
}

// 长按音符 (未来引擎升级用)
[System.Serializable]
public class LongNote1 {
    public int start;       // 起始格索引
    public int length;      // 持续多少格
    public int typeIndex;   // 1-based, 对应 NotesStatics.noteTypes
}

